package com.soukly.listing.photo;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.CRC32;
import java.util.zip.Deflater;

import javax.imageio.ImageIO;

/**
 * Images generated by the tests, never committed: JPEG with EXIF (orientation and GPS position) and XMP, PNG, and
 * files that only pretend to be images.
 */
final class TestImages {

    /** EXIF orientation "rotate 90° clockwise to display": a portrait photo stored in landscape by the camera. */
    static final int ROTATE_90 = 6;

    private TestImages() {
    }

    /** A JPEG of {@code width} × {@code height} with an EXIF block (orientation, GPS of Tunis) and an XMP packet. */
    static byte[] jpegWithMetadata(int width, int height, int orientation) {
        byte[] jpeg = encode(image(width, height), "jpg");
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        // SOI, then the APP1 segments, then the rest of the file (JFIF APP0, tables, pixels)
        out.write(jpeg, 0, 2);
        writeSegment(out, 0xe1, concat("Exif\0\0".getBytes(StandardCharsets.US_ASCII), exif(orientation)));
        writeSegment(out, 0xe1, concat("http://ns.adobe.com/xap/1.0/\0".getBytes(StandardCharsets.US_ASCII), xmp()));
        out.write(jpeg, 2, jpeg.length - 2);
        return out.toByteArray();
    }

    static byte[] jpeg(int width, int height) {
        return encode(image(width, height), "jpg");
    }

    static byte[] png(int width, int height) {
        return encode(image(width, height), "png");
    }

    /**
     * A PNG whose header declares {@code width} × {@code height} but whose pixel data is a single empty row: only
     * reading the header tells its size, decoding it would allocate the declared image.
     */
    static byte[] pngHeader(int width, int height) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.writeBytes(new byte[] { (byte) 0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n' });
        // 8 bits per sample, grayscale, deflate, adaptive filtering, no interlace
        pngChunk(out, "IHDR", ByteBuffer.allocate(13).putInt(width).putInt(height)
                .put(new byte[] { 8, 0, 0, 0, 0 }).array());
        Deflater deflater = new Deflater();
        deflater.setInput(new byte[width + 1]);
        deflater.finish();
        byte[] compressed = new byte[width + 64];
        int length = deflater.deflate(compressed);
        deflater.end();
        pngChunk(out, "IDAT", Arrays.copyOf(compressed, length));
        pngChunk(out, "IEND", new byte[0]);
        return out.toByteArray();
    }

    /** The start of a PDF document, as a file renamed {@code photo.jpg} would hold. */
    static byte[] pdf() {
        return """
                %PDF-1.4
                1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
                2 0 obj << /Type /Pages /Kids [] /Count 0 >> endobj
                trailer << /Root 1 0 R >>
                %%EOF
                """.getBytes(StandardCharsets.US_ASCII);
    }

    /** {@code size} bytes that start like a JPEG, for the size checks. */
    static byte[] bytes(int size) {
        byte[] bytes = new byte[size];
        bytes[0] = (byte) 0xff;
        bytes[1] = (byte) 0xd8;
        bytes[2] = (byte) 0xff;
        return bytes;
    }

    /** Four-character codes of the chunks of a WebP file (RIFF container), in order. */
    static List<String> webpChunks(byte[] webp) {
        ByteBuffer buffer = ByteBuffer.wrap(webp).order(ByteOrder.LITTLE_ENDIAN);
        if (!fourCc(buffer, 0).equals("RIFF") || !fourCc(buffer, 8).equals("WEBP")) {
            throw new IllegalArgumentException("Not a WebP file");
        }
        List<String> chunks = new ArrayList<>();
        int offset = 12;
        while (offset + 8 <= webp.length) {
            chunks.add(fourCc(buffer, offset));
            int size = buffer.getInt(offset + 4);
            offset += 8 + size + (size & 1);
        }
        return chunks;
    }

    /** A gradient, so the encoders have something to compress. */
    private static BufferedImage image(int width, int height) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setPaint(new GradientPaint(0, 0, new Color(0x2a2140), width, height, new Color(0xf2b33d)));
        graphics.fillRect(0, 0, width, height);
        graphics.dispose();
        return image;
    }

    private static byte[] encode(BufferedImage image, String format) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try {
            if (!ImageIO.write(image, format, out)) {
                throw new IllegalStateException("No ImageIO writer for " + format);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return out.toByteArray();
    }

    /**
     * A little-endian TIFF structure: IFD0 with the orientation and a pointer to the GPS IFD, which holds the
     * latitude and longitude of Tunis (36° 48' N, 10° 11' E).
     */
    private static byte[] exif(int orientation) {
        ByteBuffer tiff = ByteBuffer.allocate(140).order(ByteOrder.LITTLE_ENDIAN);
        tiff.put((byte) 'I').put((byte) 'I').putShort((short) 42).putInt(8);
        int gpsIfd = 8 + 2 + 2 * 12 + 4;
        // IFD0
        tiff.putShort((short) 2);
        entry(tiff, 0x0112, 3, 1, orientation);
        entry(tiff, 0x8825, 4, 1, gpsIfd);
        tiff.putInt(0);
        // GPS IFD
        int data = gpsIfd + 2 + 4 * 12 + 4;
        tiff.putShort((short) 4);
        entry(tiff, 0x0001, 2, 2, 'N');
        entry(tiff, 0x0002, 5, 3, data);
        entry(tiff, 0x0003, 2, 2, 'E');
        entry(tiff, 0x0004, 5, 3, data + 24);
        tiff.putInt(0);
        rationals(tiff, 36, 48, 0);
        rationals(tiff, 10, 11, 0);
        return Arrays.copyOf(tiff.array(), tiff.position());
    }

    /** One IFD entry whose value fits in 4 bytes (or is an offset). */
    private static void entry(ByteBuffer tiff, int tag, int type, int count, int value) {
        tiff.putShort((short) tag).putShort((short) type).putInt(count);
        if (type == 3) {
            tiff.putShort((short) value).putShort((short) 0);
        } else if (type == 2) {
            tiff.put((byte) value).put((byte) 0).put((byte) 0).put((byte) 0);
        } else {
            tiff.putInt(value);
        }
    }

    private static void rationals(ByteBuffer tiff, int degrees, int minutes, int seconds) {
        tiff.putInt(degrees).putInt(1).putInt(minutes).putInt(1).putInt(seconds).putInt(1);
    }

    private static byte[] xmp() {
        return """
                <x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">\
                <rdf:Description xmlns:exif="http://ns.adobe.com/exif/1.0/" exif:GPSLatitude="36,48N" \
                exif:GPSLongitude="10,11E"/></rdf:RDF></x:xmpmeta>""".getBytes(StandardCharsets.UTF_8);
    }

    private static void pngChunk(ByteArrayOutputStream out, String type, byte[] data) {
        byte[] typeBytes = type.getBytes(StandardCharsets.US_ASCII);
        CRC32 crc = new CRC32();
        crc.update(typeBytes);
        crc.update(data);
        out.writeBytes(ByteBuffer.allocate(4).putInt(data.length).array());
        out.writeBytes(typeBytes);
        out.writeBytes(data);
        out.writeBytes(ByteBuffer.allocate(4).putInt((int) crc.getValue()).array());
    }

    private static void writeSegment(ByteArrayOutputStream out, int marker, byte[] payload) {
        int length = payload.length + 2;
        out.write(0xff);
        out.write(marker);
        out.write(length >> 8);
        out.write(length & 0xff);
        out.write(payload, 0, payload.length);
    }

    private static byte[] concat(byte[] first, byte[] second) {
        byte[] result = Arrays.copyOf(first, first.length + second.length);
        System.arraycopy(second, 0, result, first.length, second.length);
        return result;
    }

    private static String fourCc(ByteBuffer buffer, int offset) {
        byte[] code = new byte[4];
        buffer.get(offset, code);
        return new String(code, StandardCharsets.US_ASCII);
    }
}
